"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.customer_service import CustomerService
from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int
from orders.domain.orders import Order


class CustomerInsightsController:
    def __init__(self, orders: OrderService, customers: CustomerService) -> None:
        self._orders = orders
        self._customers = customers

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with the totals the order summary reports."""
        try:
            orders = self._orders.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        # list_for_customer returns creation order; reverse it for newest first.
        history: list[dict[str, Any]] = [
            {"order_id": s.order.order_id, "status": s.order.status, "total_cents": s.total_cents}
            for s in (self._orders.summarize(o) for o in reversed(orders))
        ]
        return Response(200, {"customer_id": customer_id, "orders": history})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and total of a customer's orders, leaving out cancelled ones."""
        try:
            orders = self._orders.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        count, total = self._lifetime_value(orders)
        return Response(200, {"customer_id": customer_id, "order_count": count,
                              "lifetime_value_cents": total})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers ranked by lifetime value, highest first, ties broken by customer_id."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._customers.list_all():
            _, total = self._lifetime_value(self._orders.list_for_customer(customer.customer_id))
            if total > 0:
                ranked.append((total, customer))
        ranked.sort(key=lambda entry: (-entry[0], entry[1].customer_id))
        return Response(200, {"customers": [
            {"customer_id": c.customer_id, "name": c.name, "lifetime_value_cents": total}
            for total, c in ranked[:limit]
        ]})

    def _lifetime_value(self, orders: list[Order]) -> tuple[int, int]:
        """(number of non-cancelled orders, sum of their totals including discounts)."""
        totals = [self._orders.summarize(o).total_cents for o in orders if o.status != "cancelled"]
        return len(totals), sum(totals)

